package acesso.de.modificadores.estudando.domain;import java.util.Scanner;public class Pessoa {    private String name;    private int age;    private char sexo;    public void imprimir(){        System.out.println(this.name);        System.out.println(this.age);        System.out.println(this.sexo);    }    public void setName(String name){        this.name = name;    }    public void setAge(int age){        if ( age < 0 ) {            System.out.println("Age is invalid");            return;        }        this.age = age;    }    public String getName(){        return this.name;    }    public int getAge(){        return this.age;    }}